   139	static int
   140	_tr46 (const uint8_t * domain_u8, uint8_t ** out, int flags)
   141	{
   142	  size_t len, it;
   143	  uint32_t *domain_u32;
   144	  int err = IDN2_OK, rc;
   145	  int transitional = 0;
   146	  int test_flags;
