   235	      if (map_is (&map, TR46_FLG_DISALLOWED))
   236	        {
   237	          tmp[len2++] = c;
   238	        }
   239	      else if (map_is (&map, TR46_FLG_MAPPED))
   240	        {
   241	          len2 += get_map_data (tmp + len2, &map);
   242	        }
   243	      else if (map_is (&map, TR46_FLG_VALID))
   244	        {
   245	          tmp[len2++] = c;
   246	        }
